/*
 * kmem.c — WDM kernel driver (Windows, C)
 *
 * Exposes \\.\KMem and services two IOCTLs:
 *
 *   IOCTL_KMEM_READ   copy bytes FROM a caller-chosen VA range INTO the
 *                     caller's output buffer.
 *
 *   IOCTL_KMEM_WRITE  copy bytes FROM the caller's buffer INTO a caller-
 *                     chosen VA range.
 *
 * Both IOCTLs accept a KMEM_REQUEST header that names the target process
 * (by PID) and the base virtual address.  PID 0 means the kernel address
 * space; any other PID is looked up with PsLookupProcessByProcessId and
 * the copy is performed with MmCopyVirtualMemory.
 *
 * Build with the WDK (plain WDM, no WDF):
 *
 *   Sources file:
 *       TARGETNAME  = kmem
 *       TARGETTYPE  = DRIVER
 *       SOURCES     = kmem.c
 *
 *   Or a minimal CMakeLists.txt that calls add_library(kmem SHARED kmem.c)
 *   with the kernel compile flags set by the WDK toolchain file.
 */

#include <ntddk.h>
#include <wdm.h>

/* ------------------------------------------------------------------ */
/* Device / symbolic-link names                                        */
/* ------------------------------------------------------------------ */

#define DEVICE_NAME  L"\\Device\\KMem"
#define SYMLINK_NAME L"\\DosDevices\\KMem"

/* ------------------------------------------------------------------ */
/* IOCTL codes                                                         */
/*                                                                     */
/* METHOD_BUFFERED: the I/O manager allocates one kernel buffer whose  */
/* size is max(InputBufferLength, OutputBufferLength).  The input data */
/* is copied into it before dispatch and up to Irp->IoStatus.Information */
/* bytes are copied out of it back to the caller after completion.     */
/* ------------------------------------------------------------------ */

#define IOCTL_KMEM_READ  \
    CTL_CODE(FILE_DEVICE_UNKNOWN, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_KMEM_WRITE \
    CTL_CODE(FILE_DEVICE_UNKNOWN, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS)

/* ------------------------------------------------------------------ */
/* Hard cap on a single request (64 MB).                               */
/* ------------------------------------------------------------------ */
#define KMEM_MAX_TRANSFER ((SIZE_T)(64 * 1024 * 1024))

/* ------------------------------------------------------------------ */
/* Shared user/kernel request header                                   */
/* ------------------------------------------------------------------ */
#pragma pack(push, 1)
typedef struct _KMEM_REQUEST {
    ULONG64 ProcessId;  /* target PID; 0 = kernel address space       */
    ULONG64 Address;    /* base virtual address in target space        */
    ULONG64 Size;       /* byte count to read or write                 */
    /*
     * IOCTL_KMEM_WRITE:  data payload immediately follows this header
     *                    inside the input buffer.
     * IOCTL_KMEM_READ:   no extra input bytes; output buffer receives
     *                    the raw bytes read.
     */
} KMEM_REQUEST, *PKMEM_REQUEST;
#pragma pack(pop)

/* ------------------------------------------------------------------ */
/* MmCopyVirtualMemory — undocumented export, stable since XP SP2.    */
/* Used by NtReadVirtualMemory / NtWriteVirtualMemory internally.      */
/* ------------------------------------------------------------------ */
NTKERNELAPI
NTSTATUS
MmCopyVirtualMemory(
    _In_  PEPROCESS       FromProcess,
    _In_  PVOID           FromAddress,
    _In_  PEPROCESS       ToProcess,
    _Out_ PVOID           ToAddress,
    _In_  SIZE_T          BufferSize,
    _In_  KPROCESSOR_MODE PreviousMode,
    _Out_ PSIZE_T         NumberOfBytesCopied
);

/* ------------------------------------------------------------------ */
/* Globals                                                             */
/* ------------------------------------------------------------------ */
static PDEVICE_OBJECT g_Device = NULL;

/* ------------------------------------------------------------------ */
/* KMemCopy                                                            */
/*                                                                     */
/* Unified read/write helper.  bWrite == TRUE means copy LocalBuffer  */
/* → target address space; FALSE means copy target → LocalBuffer.     */
/* ------------------------------------------------------------------ */
static NTSTATUS
KMemCopy(
    _In_  ULONG64 TargetPid,
    _In_  ULONG64 TargetAddress,
    _In_  PVOID   LocalBuffer,
    _In_  SIZE_T  Size,
    _In_  BOOLEAN bWrite
)
{
    NTSTATUS  Status;
    PEPROCESS TargetProcess;
    PEPROCESS Self;
    SIZE_T    Copied;

    if (Size == 0 || Size > KMEM_MAX_TRANSFER) {
        return STATUS_INVALID_BUFFER_SIZE;
    }

    if (TargetPid == 0) {
        /*
         * Kernel VA: guard with SEH — the caller chose the address;
         * we must not bugcheck on a bad pointer.
         */
        __try {
            if (bWrite) {
                RtlCopyMemory((PVOID)(ULONG_PTR)TargetAddress,
                              LocalBuffer, Size);
            } else {
                RtlCopyMemory(LocalBuffer,
                              (PVOID)(ULONG_PTR)TargetAddress, Size);
            }
            Status = STATUS_SUCCESS;
        }
        __except (EXCEPTION_EXECUTE_HANDLER) {
            Status = GetExceptionCode();
        }
        return Status;
    }

    /* User process: look up the EPROCESS, then copy across spaces. */
    Status = PsLookupProcessByProcessId(
        (HANDLE)(ULONG_PTR)TargetPid, &TargetProcess);
    if (!NT_SUCCESS(Status)) {
        return Status;
    }

    Self = PsGetCurrentProcess();

    if (bWrite) {
        Status = MmCopyVirtualMemory(
            Self,                              /* from: our pool buffer */
            LocalBuffer,
            TargetProcess,                     /* to:   target process  */
            (PVOID)(ULONG_PTR)TargetAddress,
            Size, KernelMode, &Copied);
    } else {
        Status = MmCopyVirtualMemory(
            TargetProcess,                     /* from: target process  */
            (PVOID)(ULONG_PTR)TargetAddress,
            Self,                              /* to:   our pool buffer */
            LocalBuffer,
            Size, KernelMode, &Copied);
    }

    ObDereferenceObject(TargetProcess);
    return Status;
}

/* ------------------------------------------------------------------ */
/* IRP_MJ_CREATE / IRP_MJ_CLOSE                                       */
/* ------------------------------------------------------------------ */
static NTSTATUS
KMemCreateClose(
    _In_ PDEVICE_OBJECT DeviceObject,
    _In_ PIRP           Irp
)
{
    UNREFERENCED_PARAMETER(DeviceObject);
    Irp->IoStatus.Status      = STATUS_SUCCESS;
    Irp->IoStatus.Information = 0;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return STATUS_SUCCESS;
}

/* ------------------------------------------------------------------ */
/* IRP_MJ_DEVICE_CONTROL                                              */
/* ------------------------------------------------------------------ */
static NTSTATUS
KMemDeviceControl(
    _In_ PDEVICE_OBJECT DeviceObject,
    _In_ PIRP           Irp
)
{
    PIO_STACK_LOCATION Stack;
    NTSTATUS           Status;
    ULONG_PTR          Info;
    ULONG              Code;
    ULONG              InLen;
    ULONG              OutLen;
    PVOID              SysBuf;
    PKMEM_REQUEST      Req;
    SIZE_T             DataSize;
    SIZE_T             HeaderSize;

    UNREFERENCED_PARAMETER(DeviceObject);

    Status    = STATUS_INVALID_PARAMETER;
    Info      = 0;
    HeaderSize = sizeof(KMEM_REQUEST);

    Stack  = IoGetCurrentIrpStackLocation(Irp);
    Code   = Stack->Parameters.DeviceIoControl.IoControlCode;
    InLen  = Stack->Parameters.DeviceIoControl.InputBufferLength;
    OutLen = Stack->Parameters.DeviceIoControl.OutputBufferLength;
    SysBuf = Irp->AssociatedIrp.SystemBuffer;

    if (SysBuf == NULL) {
        Status = STATUS_INVALID_PARAMETER;
        goto Complete;
    }

    switch (Code) {

    /* -------------------------------------------------------------- */
    case IOCTL_KMEM_READ:
    /*
     * In:  KMEM_REQUEST describing target {PID, Address, Size}
     * Out: Size raw bytes from [Address, Address + Size)
     *
     * Both in and out share SystemBuffer (METHOD_BUFFERED).
     * We read the header first, then overwrite SystemBuffer[0..Size-1]
     * with the fetched bytes.  The I/O manager copies those back to the
     * caller's output buffer on completion.
     */
        if (InLen < (ULONG)HeaderSize) {
            Status = STATUS_BUFFER_TOO_SMALL;
            break;
        }
        Req      = (PKMEM_REQUEST)SysBuf;
        DataSize = (SIZE_T)Req->Size;

        if (DataSize == 0 || DataSize > KMEM_MAX_TRANSFER) {
            Status = STATUS_INVALID_BUFFER_SIZE;
            break;
        }
        if ((ULONG)DataSize > OutLen) {
            Status = STATUS_BUFFER_TOO_SMALL;
            break;
        }

        /*
         * Save request fields before KMemCopy overwrites SystemBuffer.
         */
        {
            ULONG64 Pid     = Req->ProcessId;
            ULONG64 Address = Req->Address;

            Status = KMemCopy(Pid, Address, SysBuf, DataSize, FALSE);
            if (NT_SUCCESS(Status)) {
                Info = (ULONG_PTR)DataSize;
            }
        }
        break;

    /* -------------------------------------------------------------- */
    case IOCTL_KMEM_WRITE:
    /*
     * In:  KMEM_REQUEST header + data payload
     * Out: nothing
     *
     * Layout of the input buffer:
     *   [0 .. sizeof(KMEM_REQUEST)-1]  header
     *   [sizeof(KMEM_REQUEST) .. +Size-1]  bytes to write
     */
        if (InLen < (ULONG)HeaderSize) {
            Status = STATUS_BUFFER_TOO_SMALL;
            break;
        }
        Req      = (PKMEM_REQUEST)SysBuf;
        DataSize = (SIZE_T)Req->Size;

        if (DataSize == 0 || DataSize > KMEM_MAX_TRANSFER) {
            Status = STATUS_INVALID_BUFFER_SIZE;
            break;
        }

        /* Overflow-safe size check: HeaderSize + DataSize <= InLen */
        if (DataSize > (SIZE_T)(InLen - HeaderSize)) {
            Status = STATUS_BUFFER_TOO_SMALL;
            break;
        }

        {
            ULONG64 Pid     = Req->ProcessId;
            ULONG64 Address = Req->Address;
            PVOID   Data    = (PUCHAR)SysBuf + HeaderSize;

            Status = KMemCopy(Pid, Address, Data, DataSize, TRUE);
        }
        break;

    /* -------------------------------------------------------------- */
    default:
        Status = STATUS_INVALID_DEVICE_REQUEST;
        break;
    }

Complete:
    Irp->IoStatus.Status      = Status;
    Irp->IoStatus.Information = Info;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return Status;
}

/* ------------------------------------------------------------------ */
/* DriverUnload                                                        */
/* ------------------------------------------------------------------ */
static VOID
KMemUnload(
    _In_ PDRIVER_OBJECT DriverObject
)
{
    UNICODE_STRING Sym = RTL_CONSTANT_STRING(SYMLINK_NAME);

    UNREFERENCED_PARAMETER(DriverObject);

    IoDeleteSymbolicLink(&Sym);

    if (g_Device != NULL) {
        IoDeleteDevice(g_Device);
        g_Device = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* DriverEntry                                                         */
/* ------------------------------------------------------------------ */
NTSTATUS
DriverEntry(
    _In_ PDRIVER_OBJECT  DriverObject,
    _In_ PUNICODE_STRING RegistryPath
)
{
    NTSTATUS       Status;
    UNICODE_STRING DevName = RTL_CONSTANT_STRING(DEVICE_NAME);
    UNICODE_STRING Sym     = RTL_CONSTANT_STRING(SYMLINK_NAME);

    UNREFERENCED_PARAMETER(RegistryPath);

    /* Create the device object. */
    Status = IoCreateDevice(
        DriverObject,
        0,
        &DevName,
        FILE_DEVICE_UNKNOWN,
        FILE_DEVICE_SECURE_OPEN,
        FALSE,
        &g_Device
    );
    if (!NT_SUCCESS(Status)) {
        return Status;
    }

    /* Both IOCTLs use METHOD_BUFFERED → set DO_BUFFERED_IO. */
    g_Device->Flags |= DO_BUFFERED_IO;
    g_Device->Flags &= ~DO_DEVICE_INITIALIZING;

    /* Expose the Win32-visible path: \\.\KMem */
    Status = IoCreateSymbolicLink(&Sym, &DevName);
    if (!NT_SUCCESS(Status)) {
        IoDeleteDevice(g_Device);
        g_Device = NULL;
        return Status;
    }

    DriverObject->DriverUnload                         = KMemUnload;
    DriverObject->MajorFunction[IRP_MJ_CREATE]         = KMemCreateClose;
    DriverObject->MajorFunction[IRP_MJ_CLOSE]          = KMemCreateClose;
    DriverObject->MajorFunction[IRP_MJ_DEVICE_CONTROL] = KMemDeviceControl;

    return STATUS_SUCCESS;
}
